// pages/CouponCenter.jsx

import React, { useEffect, useState } from 'react';
import { fetchMyCoupons, redeemCoupon } from '../api/couponApi';

function CouponCenter() {
  const [coupons, setCoupons] = useState([]);

  useEffect(() => {
    const load = async () => {
      try {
        const res = await fetchMyCoupons();
        setCoupons(res.data || []);
      } catch (err) {
        console.error('load coupons', err);
      }
    };
    load();
  }, []);

  const handleRedeem = async (id) => {
    try {
      await redeemCoupon(id);
      setCoupons(coupons.map(c => c._id === id ? { ...c, redeemed: true } : c));
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div style={{ padding: 20 }}>
      <h1>🎟️ 내 쿠폰함</h1>
      <p style={{ color: '#666' }}>룰렛 또는 이벤트로 획득한 쿠폰을 확인하세요.</p>

      <div style={{ marginTop: 16, display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(240px,1fr))', gap: 12 }}>
        {coupons.length === 0 ? (
          <div style={{ color: '#999' }}>쿠폰이 없습니다.</div>
        ) : (
          coupons.map(c => (
            <div key={c._id} style={{ padding: 12, borderRadius: 8, background: '#fff', boxShadow: '0 6px 18px rgba(0,0,0,0.04)' }}>
              <div style={{ fontWeight: 700 }}>{c.brand} - {c.discount}%</div>
              <div style={{ marginTop: 6 }}>코드: <strong>{c.code}</strong></div>
              <div style={{ marginTop: 6, color: '#666' }}>유효기간: {c.expiresAt ? new Date(c.expiresAt).toLocaleDateString() : '무제한'}</div>
              <div style={{ marginTop: 10 }}>
                {c.redeemed ? (
                  <button disabled style={{ padding: '8px 10px', borderRadius: 8, background: '#eee', border: 'none' }}>사용됨</button>
                ) : (
                  <>
                    <a href={c.externalUrl || '#'} target="_blank" rel="noreferrer"><button style={{ padding: '8px 10px', borderRadius: 8, marginRight: 8, background: '#ff6b6b', color: '#fff', border: 'none' }}>쿠팡으로 사용하러 가기</button></a>
                    <button onClick={() => handleRedeem(c._id)} style={{ padding: '8px 10px', borderRadius: 8, background: '#0070f3', color: '#fff', border: 'none' }}>사용 처리</button>
                  </>
                )}
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

export default CouponCenter;
